// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 1000000000000000000);
        c.OpenToThePublic();
    }

    function testFuzz_property(address player, uint256 difficulty) public {
        // Admissible domain: a real player EOA, and a nonzero difficulty so play() does not return early.
        vm.assume(player != address(0));
        vm.assume(player.code.length == 0);
        vm.assume(difficulty > 0);

        // Make the player a real EOA and act as them for wager().
        vm.deal(player, 1 ether);
        vm.prank(player, player);
        c.wager{value: 1 ether}();

        // Set difficulty so the game logic is well-defined.
        c.AdjustDifficulty(difficulty);

        // In the reference, play() in the SAME block must revert, so hasPlayerWagered remains true.
        bool ok = true;
        vm.prank(player, player);
        try c.play() { ok = true; } catch { ok = false; }

        // Rule: for every same-block play() attempt, the wager must still be visible.
        // Reference: revert -> ok == false, hasPlayerWagered == true.
        // Mutant:    no revert -> ok == true, hasPlayerWagered == false.
        assertTrue(!ok && c.hasPlayerWagered(player), "wager must survive a same-block play()");
    }
}
